   296→    awaitWriteFinish: { stabilityThreshold: 300 },
   297→    ignored: ["**/node_modules/**", "**/.git/**", "**/.git"],
   298→    depth: 5,
   299→  });
   300→
   301→  let debounceTimer: ReturnType<typeof setTimeout> | null = null;
   302→
   303→  const notify = (type: string, path: string): void => {
   304→    if (debounceTimer) clearTimeout(debounceTimer);
   305→    debounceTimer = setTimeout(() => {
   306→      if (!mainWindow.isDestroyed()) {
   307→        mainWindow.webContents.send(IPC.FS_CHANGED, { type, path });
   308→      }
   309→    }, 300);
   310→  };
   311→
   312→  watcher.on("add", (path) => notify("add", path));
   313→  watcher.on("change", (path) => notify("change", path));
   314→  watcher.on("unlink", (path) => notify("unlink", path));
   315→}
   316→
   317→export function cleanupHandlers(): void {
   318→  if (watcher) {
   319→    watcher.close();
   320→    watcher = null;
   321→  }
   322→}
